package com.example.smartpantrymanager.ui; import android.app.*;import android.os.*;import android.widget.*;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.data.*;import com.example.smartpantrymanager.model.*; public class AddEditPantryActivity extends Activity { protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_edit_pantry);DatabaseHelper db=new DatabaseHelper(this);EditText n=findViewById(R.id.inputName),q=findViewById(R.id.inputQuantity),u=findViewById(R.id.inputUnit);findViewById(R.id.btnSave).setOnClickListener(v->{try{db.insert(new PantryItem(0,n.getText().toString().trim(),Double.parseDouble(q.getText().toString()),u.getText().toString().trim(),"",""));finish();}catch(Exception e){Toast.makeText(this,"Enter valid item details",Toast.LENGTH_SHORT).show();}});} }